changeSet.sql:
CREATE TABLE departments ( id BIGINT GENERATED BY DEFAULT AS IDENTITY, name VARCHAR(100) NOT NULL, location VARCHAR(100), created_at TIMESTAMP WITH TIME ZONE NOT NULL, modified_at TIMESTAMP WITH TIME ZONE NOT NULL, CONSTRAINT pk_departments PRIMARY KEY (id), CONSTRAINT uk_departments_name UNIQUE (name) );
CREATE TABLE employees ( id BIGINT GENERATED BY DEFAULT AS IDENTITY, first_name VARCHAR(100) NOT NULL, last_name VARCHAR(100) NOT NULL, email VARCHAR(255) NOT NULL, job_title VARCHAR(100), hire_date DATE NOT NULL, salary NUMERIC(12, 2), department_id BIGINT NOT NULL, created_at TIMESTAMP WITH TIME ZONE NOT NULL, modified_at TIMESTAMP WITH TIME ZONE NOT NULL, CONSTRAINT pk_employees PRIMARY KEY (id), CONSTRAINT uk_employees_email UNIQUE (email), CONSTRAINT fk_employees_department FOREIGN KEY (department_id) REFERENCES departments (id), CONSTRAINT ck_employees_salary_non_negative CHECK (salary >= 0) );
CREATE INDEX idx_employees_department_id ON employees (department_id);
